import * as pc from './engine/playcanvas.min.mjs';
const $=id=>document.getElementById(id),canvas=$('canvas');
const state=window.__lingyuan={ready:false,errors:[],frames:0,renderer:null,lod:0,animation:'pose',triangles:0,drawCalls:0};
window.addEventListener('error',e=>state.errors.push(e.message));window.addEventListener('unhandledrejection',e=>state.errors.push(String(e.reason)));
let app,camera,character,device,key,fill,loaded={},gray=false,yaw=0,pitch=.04,radius=3.9,target=new pc.Vec3(0,1,0),lastX=0,lastY=0,dragging=false,prevPinch=0;
const counts=[0,0,0];
async function fetchStats(){const response=await fetch('model-stats.json');if(!response.ok)throw Error('模型统计信息加载失败');const doc=await response.json();if(doc.version!==1||!Array.isArray(doc.lods)||doc.lods.length!==3)throw Error('模型统计信息无效');for(const item of doc.lods){if(!Number.isInteger(item.lod)||item.lod<0||item.lod>2||!Number.isInteger(item.triangles)||item.triangles<1)throw Error('模型统计信息不完整');counts[item.lod]=item.triangles}}
function resize(){if(!app)return;let r=canvas.parentElement.getBoundingClientRect();app.resizeCanvas(Math.max(1,r.width),Math.max(1,r.height))}
function updateCamera(){let cp=Math.cos(pitch);camera.setPosition(target.x+radius*Math.sin(yaw)*cp,target.y+radius*Math.sin(pitch),target.z+radius*Math.cos(yaw)*cp);camera.lookAt(target)}
function withTimeout(p,ms,label){let timer;return Promise.race([p,new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error(label)),ms)})]).finally(()=>clearTimeout(timer))}
function loadModel(n){if(loaded[n])return Promise.resolve(loaded[n]);return withTimeout(new Promise((resolve,reject)=>app.assets.loadFromUrl(`lingyuan-lod${n}.glb`,'container',(e,a)=>{if(e)reject(e);else{loaded[n]=a;resolve(a)}})),45000,'模型下载超时，请检查网络后重试')}
let actorPosition=new pc.Vec3(), actorHeading=0, movementActive=false, joystick={x:0,y:0}, keys=new Set(), requestNumber=0;
let savedMaterials=[];const grayMat=new pc.StandardMaterial();grayMat.diffuse=new pc.Color(.52,.54,.56);grayMat.roughness=.65;grayMat.update();
function applyGray(){for(const {mesh,material} of savedMaterials)mesh.material=gray?grayMat:material}
async function showModel(n,animation='pose'){
 const request=++requestNumber;$('loading').hidden=false;$('load-message').textContent='正在加载模型层级…';const asset=await loadModel(n);if(request!==requestNumber)return;if(character)character.destroy();character=asset.resource.instantiateRenderEntity();app.root.addChild(character);character.setPosition(actorPosition);character.setEulerAngles(0,actorHeading,0);savedMaterials=[];
 for(const c of character.findComponents('render'))for(const mesh of c.meshInstances)savedMaterials.push({mesh,material:mesh.material});applyGray();
 let clips=asset.resource.animations;state.clips=clips.map(a=>a.resource?.name||a.name);
 character.addComponent('anim',{activate:true});
 for(const clip of clips){let name=clip.resource?.name||clip.name;character.anim.assignAnimation(name,clip.resource,undefined,1,true)}
 if(animation!=='pose'){let found=clips.find(a=>(a.resource?.name||a.name)===animation);if(found)character.anim.baseLayer.transition(animation,0);else animation='pose';}
 if(animation==='pose')character.anim.enabled=false;
 window.__lingBone=()=>{let b=character.findByName('thigh.R');if(!b)return null;let q=b.getLocalRotation();return [q.x,q.y,q.z,q.w]};state.animation=animation;state.lod=n;state.triangles=counts[n];$('triangles').textContent=Math.round(counts[n]).toLocaleString('zh-CN');$('loading').hidden=true;
}
function view(name){const presets={front:[0,.03,3.9,[0,1.05,0]],side:[Math.PI/2,.03,3.9,[0,1.05,0]],back:[Math.PI,.03,3.9,[0,1.05,0]],full:[0,.03,3.9,[0,1.05,0]],face:[0,.02,.70,[0,1.76,0]],armor:[-.30,.12,1.25,[0,1.47,0]],waist:[0,.04,1.4,[0,1.05,0]],weapon:[.2,.02,3,[.4,1.05,0]]};let p=presets[name];[yaw,pitch,radius]=p;yaw+=actorHeading*Math.PI/180;target.set(p[3][0]+actorPosition.x,p[3][1],p[3][2]+actorPosition.z);updateCamera();document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name))}
async function main(){
 const forcedWebgl=new URLSearchParams(location.search).get('renderer')==='webgl2';try{device=await withTimeout(pc.createGraphicsDevice(canvas,{deviceTypes:forcedWebgl?[pc.DEVICETYPE_WEBGL2]:[pc.DEVICETYPE_WEBGPU,pc.DEVICETYPE_WEBGL2],antialias:true,glslangUrl:'/engine/glslang.js',twgslUrl:'/engine/twgsl.js'}),forcedWebgl?25000:15000,'图形初始化超时')}catch(e){if(!forcedWebgl){switchToCompatibility();return}throw e}state.renderer=device.deviceType;$('renderer').textContent=device.deviceType==='webgpu'?'WebGPU':'WebGL 2 · 兼容模式';
 app=new pc.Application(canvas,{graphicsDevice:device});app.setCanvasFillMode(pc.FILLMODE_NONE);app.setCanvasResolution(pc.RESOLUTION_AUTO);device.maxPixelRatio=Math.min(devicePixelRatio,1.5);resize();app.scene.ambientLight=new pc.Color(.55,.58,.61);
 camera=new pc.Entity('Inspection camera');camera.addComponent('camera',{clearColor:new pc.Color(.16,.21,.26),fov:40,nearClip:.02,farClip:100});camera.camera.toneMapping=pc.TONEMAP_ACES;app.root.addChild(camera);updateCamera();
 key=new pc.Entity('Key');key.addComponent('light',{type:'directional',color:new pc.Color(1,.91,.78),intensity:1.5,castShadows:false});key.setEulerAngles(-35,35,0);app.root.addChild(key);
 fill=new pc.Entity('Fill');fill.addComponent('light',{type:'directional',color:new pc.Color(.63,.78,1),intensity:.75,castShadows:false});fill.setEulerAngles(25,-145,0);app.root.addChild(fill);
 const floorMat=new pc.StandardMaterial();floorMat.diffuse=new pc.Color(.20,.25,.30);floorMat.metalness=.25;floorMat.roughness=.6;floorMat.useMetalness=true;floorMat.update();const floor=new pc.Entity('Neutral platform');floor.addComponent('render',{type:'cylinder',material:floorMat});floor.setLocalScale(7.4,.035,7.4);floor.setPosition(0,-.035,0);app.root.addChild(floor);
 let info=device.gpuAdapter?.info;let sw=!!(info?.isFallbackAdapter||/swiftshader|llvmpipe|lavapipe/i.test([info?.vendor,info?.architecture,info?.device,info?.description].join(' ')));if(device.deviceType==='webgl2'){let gl=device.gl,e=gl.getExtension('WEBGL_debug_renderer_info');sw=!!(e&&/swiftshader|llvmpipe|software/i.test(gl.getParameter(e.UNMASKED_RENDERER_WEBGL)))}state.software=sw;
 if(sw&&device.wgpu){app.autoRender=false;app.renderNextFrame=true;app.on('postrender',()=>queueMicrotask(async()=>{await device.wgpu.queue.onSubmittedWorkDone();setTimeout(()=>{app.renderNextFrame=true},100)}))}
 app.start();await fetchStats();const initialLod=matchMedia('(max-width: 800px)').matches?1:0;$('lod').value=String(initialLod);try{await showModel(initialLod)}catch(e){if(initialLod===2)throw e;$('lod').value='2';await showModel(2)}state.ready=true;app.on('update',moveActor);if(device.deviceType==='webgpu'&&!forcedWebgl){if(device.wgpu?.lost)device.wgpu.lost.then(info=>{if(info.reason!=='destroyed')switchToCompatibility()});device.wgpu?.addEventListener('uncapturederror',()=>switchToCompatibility());setTimeout(()=>{if(!document.hidden&&state.frames===0)switchToCompatibility()},15000)}
 let then=performance.now(),frames=0;app.on('postrender',()=>{frames++;state.frames++;let now=performance.now();if(now-then>1000){$('fps').textContent=Math.round(frames*1000/(now-then));const dc=app.stats.drawCalls.total; $('draws').textContent=dc>0?dc:'—';state.drawCalls=dc>0?dc:null;then=now;frames=0}});
 window.addEventListener('resize',resize);
}
canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')return;dragging=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!dragging)return;yaw-=(e.clientX-lastX)*.008;pitch=Math.max(-.8,Math.min(.8,pitch+(e.clientY-lastY)*.008));lastX=e.clientX;lastY=e.clientY;updateCamera()});canvas.addEventListener('pointerup',()=>dragging=false);canvas.addEventListener('pointercancel',()=>dragging=false);canvas.addEventListener('wheel',e=>{e.preventDefault();radius=Math.max(.45,Math.min(6,radius*Math.exp(e.deltaY*.001)));updateCamera()},{passive:false});
canvas.addEventListener('touchstart',e=>{e.preventDefault();if(e.touches.length===1){lastX=e.touches[0].clientX;lastY=e.touches[0].clientY}if(e.touches.length===2)prevPinch=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY)},{passive:false});canvas.addEventListener('touchmove',e=>{e.preventDefault();if(e.touches.length===1){let t=e.touches[0];yaw-=(t.clientX-lastX)*.008;pitch=Math.max(-.8,Math.min(.8,pitch+(t.clientY-lastY)*.008));lastX=t.clientX;lastY=t.clientY}else if(e.touches.length===2){let d=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);if(prevPinch)radius=Math.max(.45,Math.min(6,radius*prevPinch/d));prevPinch=d}updateCamera()},{passive:false});canvas.addEventListener('touchend',()=>prevPinch=0);
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>view(b.dataset.view)));$('motion').addEventListener('change',()=>showModel(+$('lod').value,$('motion').value).catch(fail));$('lod').addEventListener('change',()=>showModel(+$('lod').value,$('motion').value).catch(fail));$('gray').addEventListener('click',()=>{gray=!gray;applyGray();$('gray').textContent=gray?'恢复原材质':'切换灰模检查'});$('light').addEventListener('change',()=>{key.light.color=$('light').value==='cool'?new pc.Color(.65,.8,1):new pc.Color(1,.91,.78);fill.light.intensity=$('light').value==='cool'?1.0:.75});

function switchMotion(name){if(!character||!character.anim)return;if(state.animation===name&&character.anim.enabled)return;character.anim.enabled=true;character.anim.baseLayer.transition(name,.15);state.animation=name;$('motion').value=name}
function moveActor(dt){
 if(!state.ready||!character)return;
 let x=joystick.x+(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0), y=joystick.y+(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);
 let length=Math.hypot(x,y);if(length>.08){x/=Math.max(1,length);y/=Math.max(1,length);const dx=x*Math.cos(yaw)+y*Math.sin(yaw),dz=-x*Math.sin(yaw)+y*Math.cos(yaw);const step=Math.min(dt,.05)*1.15;let nx=actorPosition.x+dx*step,nz=actorPosition.z+dz*step,dist=Math.hypot(nx,nz);if(dist>3.15){nx*=3.15/dist;nz*=3.15/dist}let ox=actorPosition.x,oz=actorPosition.z;actorPosition.set(nx,0,nz);target.x+=nx-ox;target.z+=nz-oz;actorHeading=Math.atan2(dx,dz)*180/Math.PI;character.setPosition(actorPosition);character.setEulerAngles(0,actorHeading,0);updateCamera();if(!movementActive)switchMotion('walk');movementActive=true}
 else if(movementActive){movementActive=false;switchMotion('idle')}
 state.position={x:actorPosition.x,y:0,z:actorPosition.z};
}
window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'].includes(k)){keys.add(k);e.preventDefault()}});
window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();joystick.x=joystick.y=0;$('joystick-knob').style.transform=''});
const stick=$('joystick');function setStick(e){const r=stick.getBoundingClientRect(),limit=r.width*.32;let x=e.clientX-(r.left+r.width/2),y=e.clientY-(r.top+r.height/2),d=Math.hypot(x,y);if(d>limit){x=x*limit/d;y=y*limit/d}joystick={x:x/limit,y:y/limit};$('joystick-knob').style.transform=`translate(${x}px,${y}px)`}
stick.addEventListener('pointerdown',e=>{e.preventDefault();stick.setPointerCapture(e.pointerId);setStick(e)});stick.addEventListener('pointermove',e=>{if(stick.hasPointerCapture(e.pointerId))setStick(e)});function stopStick(){joystick={x:0,y:0};$('joystick-knob').style.transform=''}stick.addEventListener('pointerup',stopStick);stick.addEventListener('pointercancel',stopStick);stick.addEventListener('lostpointercapture',stopStick);
$('reset-position').addEventListener('click',()=>{target.x-=actorPosition.x;target.z-=actorPosition.z;actorPosition.set(0,0,0);actorHeading=0;if(character){character.setPosition(actorPosition);character.setEulerAngles(0,0,0)}updateCamera()});

function switchToCompatibility(){const url=new URL(location.href);if(url.searchParams.get('renderer')==='webgl2')return;url.searchParams.set('renderer','webgl2');location.replace(url.toString())}
function fail(e){state.errors.push(String(e));$('loading').hidden=false;$('load-message').textContent='加载失败：'+String(e.message||e);$('load-help').textContent='可尝试兼容模式，或在手机 Chrome / 系统浏览器中打开。';$('load-help').hidden=false;$('load-compat').hidden=false;$('load-refresh').hidden=false}
main().catch(fail);
